// #536fbb «Android - בזום 200% שם התפילה הקרובה במסך הבית נשבר באמצע המילה» — עבר QA 19.11.2026 (подтвердил пользователь).
//   Факт (Pixel 6, wm density 840, шрифт 1.15): на главной имя ближайшей молитвы («מנחה», крупный шрифт) — одним словом в одну строку,
//   без переноса внутри слова. Кейс: .qa/tests/phone/qa-2026-11-19.md (Q19-01). Только просмотр. Плотность возвращается в after().
//   Как меряем: высота TextView при 200% / (высота при обычной плотности × k) = 1 строка (k = 840 / физическая плотность); нет второго
//   текстового узла с частью слова. Дерево Android хранит полный текст, поэтому глазами — скрин qa-1911/q34-home-prayer.png.
import { driver, expect } from '@wdio/globals';
import { skipWith } from '../_lib/app-0710.ts';
import { goHome, nodes } from '../_lib/readiness-1910.ts';
import { zoomOn, zoomOff, insideScreenX, linesAtZoom, wordCount } from '../_lib/app-0911.ts';
import { homePrayerNode, saveShot } from '../_lib/app-1911.ts';

describe('19.11 — зум 200% (Android): имя ближайшей молитвы на главной (#536fbb)', () => {
  before(function () { if (!driver.isAndroid) skipWith(this, 'зум через wm density — только Android'); });
  after(async () => { if (driver.isAndroid) await zoomOff(); });

  it('Q19-01 При wm density 840 имя ближайшей молитвы на главной — одно слово в одну строку, без переноса внутри слова #536fbb @android @prod-safe', async () => {
    // 1. Обычная плотность: высота одной строки имени.
    await goHome();
    const normal = await homePrayerNode();

    // 2. Зум 200%.
    await zoomOn();
    await goHome();
    const z = await homePrayerNode();
    await saveShot('q34-home-prayer.png');
    const lines = linesAtZoom(z.h, normal.h);
    console.log(`[Q-34] «${z.label}»: ${z.w}×${z.h} (обычн. ${normal.w}×${normal.h}) → ~${lines} строк(и)`);

    // Ожидаемо: имя то же, одно слово → одна строка, внутри экрана.
    expect(z.label).toBe(normal.label);
    expect(wordCount(z.label)).toBe(1);
    expect(lines).toBe(1);
    expect(await insideScreenX(z)).toBe(true);

    // Нет другого текстового узла, являющегося частью слова (кусок после переноса).
    const fragments = (await nodes()).filter((n) => n.visible && n.label !== z.label && n.label.length >= 1 && z.label.includes(n.label) && /TextView/.test(n.type));
    expect(fragments.map((n) => n.label)).toEqual([]);
  });
});
